sources=[
 {'id':'B02','title':'纽扣博物馆：收蔵品 / Collection','url':'https://button-museum.jp/item/','fact':Z('图画纽扣可利用不同表面的图画表现远近；本游戏模型是自制，不是馆藏。','Picture buttons can combine paintings on different surfaces to suggest depth. Our model is a game prop, not a museum object.')},
 {'id':'R02','title':'国立剧场：舞台名与百本杭','url':'https://www2.ntj.jac.go.jp/dglib/contents/learn/edc17/sakuhin/d2/b.html','fact':Z('该剧用稲瀬川的地名表现隅田川百本杭一带的风景。本游戏只采用借景关系。','The play uses the name Inase River for scenery associated with piles along the Sumida. Only this relationship is used in our game.')},
 {'id':'H01','title':'芭蕉纪念馆：馆概要','url':'https://www.kcf.or.jp/basho/outline/','fact':Z('免费展望庭园于1995年4月开园；公布时段9:15—16:30。本馆和庭园不是同一设施。','The free observation garden opened in April 1995; published hours are 09:15–16:30. It is distinct from the main museum.')},
 {'id':'H07','title':'江东区：芭蕉与深川','url':'https://www.city.koto.lg.jp/promotion/kotocity/bashou.html','fact':Z('芭蕉1680年迁居深川。这是人物生活史，不是今日雕像的制作年代。','Basho moved to Fukagawa in 1680. This is a date in his life, not the construction date of the present monument.')},
 {'id':'P04','title':'中央区：浜町公园部分休止','url':'https://www.city.chuo.lg.jp/a0037/machizukuri/kouenryokka/kouen/oshirase/hamachosyuuhen.html','fact':Z('公告写公园部分区域休止至2029年度。案内图不证明所有通路今天开放。','The notice describes partial closure through fiscal 2029. A park map does not establish that every path is open today.')},
 {'id':'P06','title':'用户实拍案内图与菱形外墙','url':'','fact':Z('IMG_3633(1).jpeg与IMG_3636(1).jpeg：本题用园内设施的相对布局和游乐区前景。不采用图上编号作密码。','Field photos IMG_3633(1).jpeg and IMG_3636(1).jpeg show the relative layout and the playground foreground. Map numbers are not used as a code.')},
 {'id':'M01','title':'明治座：喜昇座时代','url':'https://www.meijiza.co.jp/anniversary/era1.html','fact':Z('官方沿革将前身接到西两国露天戏棚，1873年喜昇座开场。','The official history traces the predecessor to open-air playhouses in west Ryogoku and the opening of Kisho-za in 1873.')},
 {'id':'M02','title':'明治座：久松座时代','url':'https://www.meijiza.co.jp/anniversary/era2.html','fact':Z('1879年改称久松座。','The theatre opened under the name Hisamatsu-za in 1879.')},
 {'id':'M03','title':'明治座：千歳座时代','url':'https://www.meijiza.co.jp/anniversary/era3.html','fact':Z('1885年改称千歳座；后来的明治座是此沿革的延续。','The name Chitose-za was used from 1885; the subsequent Meiji-za belongs to this history.')},
 {'id':'M04','title':'明治座诞生','url':'https://www.meijiza.co.jp/anniversary/era4.html','fact':Z('1893年以明治座之名开场。名字沿革不代表建筑从未变化。','The theatre opened as Meiji-za in 1893. Continuity of identity does not mean an unchanged building.')},
 {'id':'M07','title':'昭和的明治座','url':'https://www.meijiza.co.jp/anniversary/era7.html','fact':Z('迁到今浜町公园附近后于1928年3月4日开场。这是迁址记录，不是第五个名字。','The theatre reopened near present-day Hamacho Park on 4 March 1928. This is a relocation record, not a fifth name.')},
 {'id':'M05','title':'明治座：初次来场','url':'https://www.meijiza.co.jp/firstguide/','fact':Z('外观拍摄与持票入场不同。本游戏没有场馆合作或入场权益。','Exterior viewing and ticketed admission are different. This game does not grant theatre access or claim venue partnership.')}
]
stages=[
 {'id':'s1','title':Z('01 · 三个地址，一只画框','01 · Three addresses, one frame'),'site':Z('纽扣博物馆所在建筑附近的公共步道','Public pavement near the Button Museum building'),'type':'sequence','intro':Z('莲把三张局部稿当成三个地址。澪只有一只画框：先不要分头走，在安全的步道范围内观察同一个街角。按照由左侧远塔、经过道路标志、向馆楼方向扫视的连续关系，把三张取景卡放回画框。重点看谁遮住谁，不读广告文字。','Ren has treated three sketches as three addresses. Mio has only one frame. Stay on the safe pavement and compare them with a continuous sweep of the same corner, from the distant tower toward the museum building. Watch what overlaps what; do not read the advertising text.'),
 'prompt':Z('点选三张卡放入画框；错了可清空。按现场连续视野排列后，确认前景遮挡属于真实观察，而不是图画破损。','Tap three cards into the frame; clear it to retry. Reconstruct the continuous view, then identify whether the missing details are occlusion or damage.'),
 'cards':[{'id':'roof','label':Z('馆楼／屋顶边缘','Building / roof edge'),'icon':'roof'}, {'id':'tower','label':Z('远塔与前景建筑','Distant tower / nearer block'),'icon':'tower'}, {'id':'sign','label':Z('交通牌／后方广告','Traffic sign / advertisement'),'icon':'sign'}],
 'fields':[{'id':'reading','label':Z('应采用哪种读取方式？','Which reading is justified?'),'options':[['occlusion',Z('保留前景：不同层次组成同一街景','Keep the foreground: the layers belong to one view')],['damage',Z('补出所有缺失文字，当成完整地址','Invent the missing text and treat each as an address')],['touch',Z('移动现场路牌来恢复画面','Move the real sign to reveal the view')]]}],
 'answer':{'order':['tower','sign','roof'],'reading':'occlusion'},'hints':[Z('不要猜被遮住的字，也不要走进车道。先给三幅图找同一个观察区域。','Do not guess hidden letters or step into the road. Look for a viewing area shared by the three scenes.'),Z('远塔在连续扫视的一端，馆楼在另一端，路牌对应中间一段。','The tower and the museum building occupy opposite ends of the sweep. The road-sign scene goes between them.'),Z('顺序是远塔→交通牌→馆楼。遮挡不是图画破损；保留前景。','Use tower → sign → building. Treat the missing parts as occlusion, not damage.')],
 'success':Z('三张图装成同一街角。翻开景层，河岸木杭与“稲瀬川百本杭”的舞台题签相接。保留整块景片：下一站两国桥要判断，这个名字是否真是地址。','The three views form one corner. The scenery layer joins a riverside-pile drawing to the caption “Inase River: the piles.” Keep the whole frame. At Ryogoku Bridge, test whether a scenery name is also an address.'),'lead':Z('前往两国桥。新问题：景片为什么写着另一座城市的河名？','Continue to Ryogoku Bridge. Why does the scenery carry a river name from another city?'),'evidence':'ONE_VIEW','sources':['B02'],'minutes':[6,9]},
 {'id':'s2','title':Z('02 · 把河流和舞台分开','02 · Separate the river from the stage'),'site':Z('两国桥步道／东岸公开说明区域','Ryogoku Bridge pavement / public east-bank information area'),'type':'river','intro':Z('莲没有读错“稲瀬川”，他把它放错了栏目。用真实的主河、支流口和桥校正自带示意图；再拿第一站景片，核对百本杭公开说明与简译。图不按米数绘制，旧桥位置只作示意，不要求精密重叠。','Ren has not misread “Inase River”; he has put it in the wrong field. Orient the schematic using the main river, tributary and bridge. Compare your first scene with the riverside-pile interpretation panel and its translation. The diagram is not to scale, and the old bridge is only schematically indicated.'),
 'prompt':Z('将图转到指北针朝上、支流从正确岸进入，再把两条签放入正确栏目。','Set the diagram north-up with the tributary entering from the correct bank. Then assign the two labels.'),
 'fields':[{'id':'stage','label':Z('舞台称呼','Stage name'),'options':[['inase',Z('稲瀬川 / Inase','Inase River')],['sumida',Z('隅田川 / Sumida','Sumida River')]]},{'id':'place','label':Z('真实借景地','Real scenery'),'options':[['sumida',Z('隅田川 / Sumida','Sumida River')],['inase',Z('稲瀬川 / Inase','Inase River')]]}],
 'answer':{'rotation':0,'mirror':False,'stage':'inase','place':'sumida'},'hints':[Z('先看支流汇入口相对两国桥在哪一侧；不要用水流或船的移动当指南针。','Locate the tributary relative to Ryogoku Bridge. Moving water or boats are not compasses.'),Z('正确北向图中，支流从主河的左上方进入。两个河名不需要相互删除。','On the north-up diagram the tributary enters from the upper left. You do not need to delete either river name.'),Z('恢复上方为北、左上方为支流。舞台签放稲瀬川，现实签放隅田川。','Restore north at the top and the branch at upper left. Stage: Inase. Actual scenery: Sumida.')],
 'success':Z('去镰仓的投递被撤回。河的舞台名与真实景都保留；这不是假地名。莲转而声称旅人照片是1930年原始摄影。现在去芭蕉免费区域，核验他这张日期便签。','The Kamakura delivery is withdrawn. Both the stage name and the real river are retained. Ren now claims the traveller photograph is an original from 1930. At the free Basho area, test his date note.'),'lead':Z('前往芭蕉免费展望庭园；不是收费本馆展厅。','Continue to the free Basho observation garden, not the ticketed exhibition.'),'evidence':'BORROWED_SUMIDA','sources':['R02'],'minutes':[10,15]},
 {'id':'s3','title':Z('03 · 同一张图，两条时间线','03 · One image, two timelines'),'site':Z('芭蕉庵史迹展望庭园，开放时段内','Basho-an observation garden, during open hours'),'type':'timeline','intro':Z('REN便签写“1930原始摄影”，但题图参照的是你眼前这组纪念设施。先找到题图所画的对象，再查看像座和官方年代卡。把人物在深川生活的年代，与这组设施最早可能被拍到的年代分开。不要等铜像转动，不要以今天朝向推断旧照片。','Ren’s note says “original photograph, 1930,” but the reference shows this commemorative setting. Find the depicted object and check its plaque and the official date card. Separate the person’s history from the earliest possible date of this view. Do not wait for the statue to turn or infer a date from its orientation.'),
 'fields':[{'id':'life','label':Z('芭蕉迁居深川','Basho moved to Fukagawa'),'options':[[1680,'1680'],[1930,'1930'],[1995,'1995']]},{'id':'earliest','label':Z('题图所示现代设施的摄影年代下界','Lower bound for a photograph of this setting'),'options':[[1930,'1930'],[1981,'1981'],[1995,'1995']]},{'id':'dateMeaning','label':Z('这个下界究竟能证明什么？','What does this lower bound establish?'),'options':[['lower_bound',Z('1995年或之后；不能推出具体拍摄年','1995 or later; not the exact year')],['exact',Z('必定摄于1995年','Exactly 1995')],['1930',Z('纪念古人，所以1930一定成立','It commemorates an old person, so 1930 must be valid')]]}],
 'answer':{'life':1680,'earliest':1995,'dateMeaning':'lower_bound'},'hints':[Z('诗人的年代、纪念物的年代、拍摄时间是三个不同问题。','The person, the memorial and the photograph have different dates.'),Z('官方资料注明庭园开园1995年；牌上平成七年可换算为1995。','The official sheet dates the garden to 1995. Heisei 7 also converts to 1995.'),Z('迁居1680；题图设施摄影不早于1995；不能仅凭这一点说恰好摄于1995。','Move: 1680. Photograph: no earlier than 1995. The exact year is not established.')],
 'success':Z('1930原始摄影的主张被排除；货物仍是一件可成立的当代历史借景方案。莲承认日期是自己的估计，不是伊都的原件。你们要公开列出他的异议，还是交换来源继续调查？','The 1930 claim is excluded; the contemporary historical-scene project remains viable. Ren admits that the date was his estimate, not Ito’s original statement. Will you formally challenge him, or exchange sources?'),'lead':Z('经既有安全路线回浜町公园；不用去找新的景点。','Return to Hamacho Park by the existing safe route. No additional landmark is required.'),'evidence':'MODERN_REFERENCE','sources':['H01','H07'],'minutes':[7,11]},
 {'id':'s4','title':Z('04 · 这座楼不是收件人','04 · This building is not the recipient'),'site':Z('浜町公园：案内图与游乐区一侧开放通道','Hamacho Park: map and open path on the playground side'),'type':'park','intro':Z('澪以为菱形外墙像剧场，莲则把描图纸翻反了。你们都有可能被自己的解释带偏。对照真实案内图，让河边、大场地和体育中心同时归位，再用“游乐设施在前、大楼在后”的题图确定相机侧。只操作自己的纸，不沿示意线进入封闭区。','Mio has mistaken the diamond facade for a theatre. Ren has viewed his tracing from the back. Either explanation may mislead you. Match river edge, large field and sports centre to the real map, then use the playground-in-front photograph to locate the camera side. Work on your own sheet; do not follow diagram lines into closed areas.'),
 'fields':[{'id':'camera','label':Z('哪一侧能产生题图的前后关系？','Which camera side gives the reference view?'),'options':[['playground',Z('游乐区域一侧','Playground side')],['river',Z('河岸一侧','River side')],['entrance',Z('圆形主入口一侧','Circular-entrance side')],['field',Z('大运动场一侧','Large-field side')]]},{'id':'building','label':Z('题图中的大楼','Building in the reference'),'options':[['sports',Z('体育中心','Sports centre')],['theatre',Z('明治座','Meijiza')]]},{'id':'purpose','label':Z('本页在原件中的用途','Purpose of this page'),'options':[['capture',Z('CAPTURE AT：取景定位','CAPTURE AT: view location')],['delivery',Z('DELIVER TO：收件地址','DELIVER TO: recipient address')]]}],
 'answer':{'rotation':0,'mirror':False,'camera':'playground','building':'sports','purpose':'capture'},'hints':[Z('先同时匹配最大的三件东西。仅让河边方向对上，不足以排除镜像。','Match three large anchors together. Aligning only the river edge will not rule out a mirror image.'),Z('案内图以河侧为图上方：大场地在左，体育中心在右，游乐区在体育中心另一侧。','With the river edge at the top of the reference map, the large field is left and the centre is right; the playground is beyond the centre.'),Z('校正图后选游乐区侧、体育中心、取景定位。不要把这张外景图当剧院投递地址。','Restore the map and select playground side, sports centre, capture location. This is not the theatre’s delivery address.')],
 'success':Z('澪撤回“这是剧院”，莲撤回反看描图纸的方向。取景位置已确定，但收件身份仍是千歳座的今日延续。去明治座外核对这条名字链，不是去买票。','Mio withdraws “this is the theatre”; Ren corrects his reversed tracing. The camera position is settled, but the recipient is still the present identity descended from Chitose-za. Verify that chain outside Meijiza; do not buy an entry ticket.'),'lead':Z('前往明治座外观，完成短时身份核对。','Continue to Meijiza’s exterior for a short identity check.'),'evidence':'CAPTURE_NOT_DELIVERY','sources':['P06','P04','M07'],'minutes':[12,18]},
 {'id':'s5','title':Z('05 · 名字会换，证据不能混','05 · Names can change; evidence cannot be mixed'),'site':Z('明治座外公共步道；不挡入口','Public pavement by Meijiza; keep entrances clear'),'type':'lineage','intro':Z('莲很早就猜到了明治座。只猜中这个名字，还不足以说明包裹送对了。连接旧名沿革，核对今天的竖招；把1928迁址条放在“位置变化”栏，不创造第五个名字。签收发生在你们的游戏回执里，真实剧院员工不是NPC。','Ren guessed Meijiza early. That name alone does not establish a correct delivery. Connect the historical names and check the present sign. Put the 1928 move under location history, not as a fifth name. The delivery is verified on your game receipt; theatre staff are not game characters.'),
 'cards':[{'id':'chitose','label':Z('千歳座 · 1885','Chitose-za · 1885')},{'id':'meiji','label':Z('明治座 · 1893','Meiji-za · 1893')},{'id':'kisho','label':Z('喜昇座 · 1873','Kisho-za · 1873')},{'id':'hisamatsu','label':Z('久松座 · 1879','Hisamatsu-za · 1879')}],
 'fields':[{'id':'move','label':Z('1928年应放进哪个栏目？','Where does 1928 belong?'),'options':[['location',Z('同一身份链中的迁址与再开场','Relocation/reopening within the identity history')],['fifth',Z('第五个剧场名字','A fifth theatre name')]]}],
 'answer':{'order':['kisho','hisamatsu','chitose','meiji'],'move':'location'},'hints':[Z('名字链和建筑/位置链不是同一行。','Names and buildings/locations form different tracks.'),Z('喜昇座先于久松座，千歳座在明治座之前。','Kisho-za precedes Hisamatsu-za; Chitose-za precedes Meiji-za.'),Z('喜昇座→久松座→千歳座→明治座；1928放迁址栏。','Kisho → Hisamatsu → Chitose → Meiji. Put 1928 under relocation.')],
 'success':Z('旧名找到当代对应身份。现在把五站的证据填成一份没有自相矛盾的回执：景在哪里、戏里叫什么、材料属于什么年代、哪个是取景点、交付什么。','The old name has a present-day counterpart. Now combine all five stations into a consistent receipt: scenery, stage name, date class, camera location and actual delivery.'),'lead':Z('移到不妨碍通行的允许停留处再展开全部道具；必要时回公园原停留点。','Move to an allowed stopping place before spreading the kit; return to the earlier park stop when appropriate.'),'evidence':'MEIJI_LINEAGE','sources':['M01','M02','M03','M04','M07','M05'],'minutes':[4,7]}
]
